use serde::{Serialize,Deserialize};
use serde_json::{Value,json};
use std::{collections::{BTreeMap,HashSet},fs,io::{Read,Cursor},net::{IpAddr,ToSocketAddrs},path::{Path,PathBuf},sync::Mutex,time::Duration};
use sha2::{Digest,Sha256};
pub const MAX_PACKAGE:usize=20*1024*1024;
pub static LOCK:Mutex<()>=Mutex::new(());
pub type Result<T>=std::result::Result<T,String>;
#[derive(Clone,Serialize,Deserialize)] pub struct Installed {pub manifest:Value,pub enabled:bool,pub source:String}
fn err(e:impl std::fmt::Display)->String{e.to_string()}
pub fn safe_path(s:&str)->Result<()> {
 if s.is_empty()||s.len()>240||s.starts_with('/')||s.contains(['\\',':','\0']) {return Err("Invalid package path".into())}
 for part in s.trim_end_matches('/').split('/') {let stem=part.split('.').next().unwrap_or("").trim_end().to_uppercase();if part.is_empty()||part=="."||part==".."||part.ends_with(['.',' '])||part.chars().any(|c| c<' '||"<>\"|?*".contains(c))||["CON","PRN","AUX","NUL","CONIN$","CONOUT$","COM0","LPT0","COM¹","COM²","COM³","LPT¹","LPT²","LPT³","COM1","COM2","COM3","COM4","COM5","COM6","COM7","COM8","COM9","LPT1","LPT2","LPT3","LPT4","LPT5","LPT6","LPT7","LPT8","LPT9"].contains(&stem.as_str()){return Err("Unsafe package path".into())}}
 let ext=s.rsplit('.').next().unwrap_or("").to_ascii_lowercase();if ["exe","dll","com","bat","cmd","ps1","msi","scr","lnk","vbs","hta","sys","pif","cpl","jar","sh"].contains(&ext.as_str()){return Err("Executable package content".into())}Ok(())
}
pub fn version(s:&str)->Result<[u32;3]>{let a=s.split('.').map(|x|if x.is_empty()||!x.bytes().all(|b|b.is_ascii_digit()){Err("Invalid version".into())}else{x.parse().map_err(err)}).collect::<Result<Vec<u32>>>()?;a.try_into().map_err(|_|"Version must contain three numbers".into())}
pub fn validate_manifest(v:&Value)->Result<()> {
 for k in ["id","name","author","version","minDeskBoxVersion","type"]{if v[k].as_str().is_none_or(|s|s.is_empty()||s.len()>512){return Err(format!("Missing/invalid {k}"))}}
 let id=v["id"].as_str().unwrap();if id.len()>120||id.split('.').count()<2||id.split('.').any(|s|s.is_empty()||s.starts_with('-')||s.ends_with('-')||!s.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'-')) {return Err("Invalid reverse-domain ID".into())}
 if v["apiVersion"]!=1{return Err("Unsupported plugin API".into())}version(v["version"].as_str().unwrap())?;if version(v["minDeskBoxVersion"].as_str().unwrap())?>version(env!("CARGO_PKG_VERSION"))?{return Err("Newer DeskBox required".into())}
 match v["type"].as_str(){Some("theme")=>(),Some("widget")=>safe_path(v["entry"].as_str().ok_or("Missing entry")?)?,_=>return Err("Invalid plugin type".into())}
 if let Some(p)=v.get("permissions"){if !p.is_object()||p.as_object().unwrap().keys().any(|k|!["network","systemMetrics"].contains(&k.as_str())){return Err("Invalid permissions".into())}if let Some(n)=p.get("network"){for o in n.as_array().ok_or("Invalid network permissions")? {let s=o.as_str().ok_or("Invalid origin")?;let u=https(s)?;if u.origin().ascii_serialization()!=s.trim_end_matches('/'){return Err("Network permission must be an origin".into())}}}if p.get("systemMetrics").is_some_and(|s|!s.is_boolean()){return Err("Invalid metrics permission".into())}}
 for key in ["updateUrl","homepage"]{if let Some(s)=v.get(key){https(s.as_str().ok_or("Invalid URL")?)?;}}Ok(())
}
pub fn validate_package(bytes:&[u8])->Result<(Value,BTreeMap<String,Vec<u8>>)> {
 if bytes.len()>MAX_PACKAGE{return Err("Package exceeds 20 MiB".into())}let mut z=zip::ZipArchive::new(Cursor::new(bytes)).map_err(err)?;if z.len()>512{return Err("Too many package entries".into())}let mut names=HashSet::new();let mut files=BTreeMap::new();let mut total=0usize;
 for i in 0..z.len(){let mut f=z.by_index(i).map_err(err)?;let name=f.name().to_owned();safe_path(&name)?;if !names.insert(name.trim_end_matches('/').to_lowercase()){return Err("Duplicate or case-colliding path".into())}if f.unix_mode().is_some_and(|m|m&0o170000!=0&&m&0o170000!=0o100000&&m&0o170000!=0o040000){return Err("Links and special files prohibited".into())}if f.is_dir(){continue}if f.size()>10*1024*1024{return Err("File exceeds 10 MiB".into())}let mut b=vec![];f.by_ref().take(10*1024*1024+1).read_to_end(&mut b).map_err(err)?;total+=b.len();if b.len()>10*1024*1024||total>50*1024*1024{return Err("Expanded package exceeds limit".into())}files.insert(name,b);}
 let manifest:Value=serde_json::from_slice(files.get("manifest.json").ok_or("Missing root manifest.json")?).map_err(err)?;validate_manifest(&manifest)?;
 let entry=if manifest["type"]=="theme"{"theme.json"}else{manifest["entry"].as_str().unwrap()};if !files.contains_key(entry){return Err("Missing plugin entry".into())}if manifest["type"]=="theme"{let t:Value=serde_json::from_slice(&files[entry]).map_err(err)?;validate_theme(&t,&files)?;}Ok((manifest,files))
}
fn safe_theme_functions(s:&str)->bool{if s.contains("/*"){return false}let allowed=["rgb","rgba","hsl","hsla","oklch","lab","lch","oklab","linear-gradient","radial-gradient","conic-gradient","repeating-linear-gradient","repeating-radial-gradient","repeating-conic-gradient","calc","clamp","min","max","var","color","color-mix"];for(i,c)in s.char_indices(){if c=='(' {let name=s[..i].trim_end().chars().rev().take_while(|c|c.is_ascii_alphabetic()||*c=='-').collect::<Vec<_>>().into_iter().rev().collect::<String>().to_ascii_lowercase();if !name.is_empty()&&!allowed.contains(&name.as_str()){return false}}}true}
pub fn validate_theme(t:&Value,files:&BTreeMap<String,Vec<u8>>)->Result<()> {if let Some(image)=t.get("backgroundImage"){let name=image.as_str().ok_or("Invalid theme background")?;safe_path(name)?;let ext=name.rsplit('.').next().unwrap_or("").to_ascii_lowercase();if !["png","jpg","jpeg","webp","gif"].contains(&ext.as_str())||!files.contains_key(name){return Err("Theme background must be a package raster image".into())}}let vars=t.get("variables").unwrap_or(t).as_object().ok_or("Theme must be a variable map")?;for(k,v)in vars{if k=="backgroundImage"&&t.get("variables").is_none(){continue}if !["--db-plugin-background","--db-plugin-color","--db-plugin-accent","--db-plugin-border","--db-plugin-radius","--db-plugin-shadow","--db-plugin-font"].contains(&k.as_str()){return Err(format!("Unsupported theme variable {k}"))}let s=v.as_str().ok_or("Theme value must be text")?;if s.len()>512||!safe_theme_functions(s)||s.contains([';','{','}','<','>','\\','@'])||["url(","image-set(","image(","src(","expression"].iter().any(|x|s.to_lowercase().chars().filter(|c|!c.is_whitespace()).collect::<String>().contains(x)){return Err("Unsafe theme value".into())}}Ok(())}
pub fn https(s:&str)->Result<url::Url>{let u=url::Url::parse(s).map_err(err)?;if u.scheme()!="https"||u.host_str().is_none()||!u.username().is_empty()||u.password().is_some(){return Err("Only public HTTPS URLs are allowed".into())}Ok(u)}
pub fn public_ip(ip:IpAddr)->bool {match ip{IpAddr::V4(a)=>{let o=a.octets();!(a.is_private()||a.is_loopback()||a.is_link_local()||a.is_broadcast()||a.is_documentation()||a.is_unspecified()||o[0]==0||o[0]>=224||o[0]==192&&o[1]==0&&o[2]==0||o[0]==192&&o[1]==88&&o[2]==99||o[0]==100&&(64..=127).contains(&o[1])||o[0]==198&&(o[1]==18||o[1]==19))},IpAddr::V6(a)=>{if let Some(v)=a.to_ipv4_mapped(){return public_ip(v.into())}let s=a.segments();s[0]&0xe000==0x2000&&!(s[0]==0x2001&&(s[1]==0xdb8||s[1]<=0x1ff))}}}
pub fn download(s:&str,limit:usize,origins:Option<&[String]>)->Result<(u16,String,Vec<u8>)>{let mut u=https(s)?;for _ in 0..6{if origins.is_some_and(|o|!o.iter().any(|s|s.trim_end_matches('/')==u.origin().ascii_serialization())){return Err("Network origin not authorized".into())}let host=u.host_str().unwrap().to_owned();let addrs=(host.as_str(),u.port_or_known_default().unwrap()).to_socket_addrs().map_err(err)?.collect::<Vec<_>>();if addrs.is_empty()||addrs.iter().any(|a|!public_ip(a.ip())){return Err("Private or reserved network address prohibited".into())}let client=reqwest::blocking::Client::builder().no_proxy().redirect(reqwest::redirect::Policy::none()).timeout(Duration::from_secs(20)).connect_timeout(Duration::from_secs(8)).resolve_to_addrs(&host,&addrs).build().map_err(err)?;let response=client.get(u.clone()).send().map_err(err)?;if response.status().is_redirection(){let location=response.headers().get("location").ok_or("Redirect missing location")?.to_str().map_err(err)?;u=https(u.join(location).map_err(err)?.as_str())?;continue}if !response.status().is_success(){return Err(format!("HTTP {}",response.status()))}if response.content_length().is_some_and(|n|n>limit as u64){return Err("Response too large".into())}let status=response.status().as_u16();let ct=response.headers().get("content-type").and_then(|v|v.to_str().ok()).unwrap_or("").to_owned();let mut b=vec![];response.take(limit as u64+1).read_to_end(&mut b).map_err(err)?;if b.len()>limit{return Err("Response too large".into())}return Ok((status,ct,b))}Err("Too many redirects".into())}
pub fn root(dir:&Path)->PathBuf{dir.join("plugins")}
pub fn list(dir:&Path)->Result<Vec<Installed>> {let p=root(dir).join("registry.json");match fs::read(p){Ok(b)=>serde_json::from_slice(&b).map_err(err),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>Ok(vec![]),Err(e)=>Err(err(e))}}
pub fn save(dir:&Path,items:&[Installed])->Result<()> {let r=root(dir);fs::create_dir_all(&r).map_err(err)?;let tmp=r.join("registry.json.tmp");fs::write(&tmp,serde_json::to_vec_pretty(items).map_err(err)?).map_err(err)?;fs::rename(tmp,r.join("registry.json")).map_err(err)}
pub fn installed(dir:&Path,id:&str)->Result<Installed>{list(dir)?.into_iter().find(|p|p.manifest["id"]==id).ok_or("Plugin not installed".into())}
pub fn preview(dir:&Path,bytes:&[u8],source:&str,sha:Option<&str>)->Result<Value>{let(m,_)=validate_package(bytes)?;if let Some(s)=sha{if format!("{:x}",Sha256::digest(bytes))!=s.to_lowercase(){return Err("SHA256 mismatch".into())}}let token=uuid::Uuid::new_v4().to_string();let staging=root(dir).join("previews");fs::create_dir_all(&staging).map_err(err)?;fs::write(staging.join(format!("{token}.zip")),bytes).map_err(err)?;fs::write(staging.join(format!("{token}.json")),serde_json::to_vec(&json!({"source":source})).map_err(err)?).map_err(err)?;let previous=list(dir)?.iter().find(|p|p.manifest["id"]==m["id"]).map(|p|p.manifest["version"].clone());Ok(json!({"token":token,"manifest":m,"source":source,"previousVersion":previous}))}
pub fn commit(dir:&Path,token:&str)->Result<Installed>{uuid::Uuid::parse_str(token).map_err(err)?;let previews=root(dir).join("previews");let bytes=fs::read(previews.join(format!("{token}.zip"))).map_err(err)?;let meta:Value=serde_json::from_slice(&fs::read(previews.join(format!("{token}.json"))).map_err(err)?).map_err(err)?;let(manifest,files)=validate_package(&bytes)?;let id=manifest["id"].as_str().unwrap();let r=root(dir);let staging=r.join(format!("stage-{token}"));fs::create_dir_all(&staging).map_err(err)?;for(n,b)in files{let p=staging.join(n);fs::create_dir_all(p.parent().unwrap()).map_err(err)?;fs::write(p,b).map_err(err)?;}let dest=r.join("installed").join(id);fs::create_dir_all(dest.parent().unwrap()).map_err(err)?;let backup=r.join(format!("backup-{token}"));let mut items=list(dir)?;let had=dest.exists();if had{fs::rename(&dest,&backup).map_err(err)?}if let Err(e)=fs::rename(&staging,&dest){if had{let _=fs::rename(&backup,&dest);}return Err(err(e))}let enabled=items.iter().find(|p|p.manifest["id"]==id).map(|p|p.enabled).unwrap_or(false);let item=Installed{manifest,enabled,source:meta["source"].as_str().unwrap_or("").into()};items.retain(|p|p.manifest["id"]!=item.manifest["id"]);items.push(item.clone());if let Err(e)=save(dir,&items){let _=fs::remove_dir_all(&dest);if had{let _=fs::rename(&backup,&dest);}return Err(e)}if had{let _=fs::remove_dir_all(backup);}let _=fs::remove_file(previews.join(format!("{token}.zip")));let _=fs::remove_file(previews.join(format!("{token}.json")));Ok(item)}
#[cfg(test)] mod package_tests {
 use super::*;use std::io::Write;
 fn package(entries:&[(&str,&[u8])])->Vec<u8>{let mut z=zip::ZipWriter::new(Cursor::new(vec![]));for(n,b)in entries{z.start_file(*n,zip::write::SimpleFileOptions::default()).unwrap();z.write_all(b).unwrap();}z.finish().unwrap().into_inner()}
 fn manifest()->Vec<u8>{serde_json::to_vec(&json!({"id":"org.example.clock","name":"Clock","author":"Me","version":"1.0.0","apiVersion":1,"type":"widget","entry":"clock.html","minDeskBoxVersion":"0.1.0"})).unwrap()}
 #[test]fn duplicate_and_case_collision_rejected(){let m=manifest();let bytes=package(&[("manifest.json",&m),("MANIFEST.JSON",&m),("clock.html",b"hi")]);assert!(validate_package(&bytes).is_err());let mut duplicate=bytes.clone();for i in 0..duplicate.len()-13{if &duplicate[i..i+13]==b"MANIFEST.JSON"{duplicate[i..i+13].copy_from_slice(b"manifest.json");}}assert!(validate_package(&duplicate).is_err());}
 #[test]fn decompression_bomb_rejected(){let m=manifest();let huge=vec![0u8;10*1024*1024+1];assert!(validate_package(&package(&[("manifest.json",&m),("clock.html",&huge)])).is_err())}
 #[test]fn failed_update_keeps_old_plugin_and_data(){let dir=std::env::temp_dir().join(format!("deskbox-plugin-test-{}",uuid::Uuid::new_v4()));let m=manifest();let good=package(&[("manifest.json",&m),("clock.html",b"old")]);let first=preview(&dir,&good,"test",None).unwrap();commit(&dir,first["token"].as_str().unwrap()).unwrap();let settings=root(&dir).join("data/org.example.clock/settings.json");fs::create_dir_all(settings.parent().unwrap()).unwrap();fs::write(&settings,b"private").unwrap();let second=preview(&dir,&good,"update",None).unwrap();let token=second["token"].as_str().unwrap();fs::write(root(&dir).join("previews").join(format!("{token}.zip")),b"bad").unwrap();assert!(commit(&dir,token).is_err());assert_eq!(fs::read(root(&dir).join("installed/org.example.clock/clock.html")).unwrap(),b"old");assert_eq!(fs::read(settings).unwrap(),b"private");fs::remove_dir_all(dir).unwrap();}
 #[test]fn shipped_examples_validate(){for n in ["clock","mist"]{let path=Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("deliverables/plugins/{n}-1.0.0.deskbox-plugin"));validate_package(&fs::read(path).unwrap()).unwrap();}}
 #[test]fn network_protocol_address_permission_denials(){assert!(download("http://example.com",32,None).is_err());assert!(download("https://127.0.0.1",32,None).is_err());assert!(download("https://example.com",32,Some(&[])).is_err());}
}
#[cfg(test)]mod expanded_security_tests {
 use super::*;use std::io::Write;
 #[test]fn symlink_rejected(){let mut z=zip::ZipWriter::new(Cursor::new(vec![]));z.add_symlink("escape","../private",zip::write::SimpleFileOptions::default()).unwrap();assert!(validate_package(&z.finish().unwrap().into_inner()).is_err())}
 #[test]fn file_count_rejected(){let mut z=zip::ZipWriter::new(Cursor::new(vec![]));for n in 0..513{z.start_file(format!("{n}.txt"),zip::write::SimpleFileOptions::default()).unwrap();}assert!(validate_package(&z.finish().unwrap().into_inner()).is_err())}
 #[test]fn total_expansion_rejected(){let mut z=zip::ZipWriter::new(Cursor::new(vec![]));let file=vec![0u8;9*1024*1024];for n in 0..6{z.start_file(format!("{n}.txt"),zip::write::SimpleFileOptions::default()).unwrap();z.write_all(&file).unwrap();}assert!(validate_package(&z.finish().unwrap().into_inner()).is_err())}
 #[test]fn theme_only_package_raster_background(){let mut files=BTreeMap::new();files.insert("assets/a.png".into(),vec![]);assert!(validate_theme(&json!({"variables":{"--db-plugin-color":"#fff"},"backgroundImage":"assets/a.png"}),&files).is_ok());assert!(validate_theme(&json!({"variables":{},"backgroundImage":"https://evil/a.png"}),&files).is_err());assert!(validate_theme(&json!({"--db-plugin-background":"u\\72l(https://evil)"}),&files).is_err());assert!(validate_theme(&json!({"--db-plugin-color":"#fff;display:none"}),&files).is_err());assert!(validate_theme(&json!({"--db-plugin-background":r#"image-set("https://evil/image.png" 1x)"#}),&files).is_err());}
}

pub fn trusted_window_label(label:&str,read:bool)->bool{let indexed=|prefix:&str|label.strip_prefix(prefix).is_some_and(|n|!n.is_empty()&&n.bytes().all(|b|b.is_ascii_digit()));label=="settings"||label=="ball"||indexed("overlay-")||read&&indexed("quickbar-")}
#[cfg(test)]mod final_security_tests{use super::*;
#[test]fn command_labels(){assert!(trusted_window_label("quickbar-0",true));assert!(!trusted_window_label("quickbar-0",false));for s in ["plugin","quickbar-x","overlay-","overlay-0-evil","https://evil"]{assert!(!trusted_window_label(s,true));}assert!(trusted_window_label("overlay-12",false));}
#[test]fn registry_write_failure_rolls_back(){use std::io::Write;let dir=std::env::temp_dir().join(format!("deskbox-plugin-rollback-{}",uuid::Uuid::new_v4()));let archive=|text:&[u8]|{let mut z=zip::ZipWriter::new(Cursor::new(vec![]));z.start_file("manifest.json",zip::write::SimpleFileOptions::default()).unwrap();z.write_all(br#"{"id":"org.example.rollback","name":"Rollback","author":"Me","version":"1.0.0","apiVersion":1,"type":"widget","entry":"clock.html","minDeskBoxVersion":"0.1.0"}"#).unwrap();z.start_file("clock.html",zip::write::SimpleFileOptions::default()).unwrap();z.write_all(text).unwrap();z.finish().unwrap().into_inner()};let first=preview(&dir,&archive(b"old"),"test",None).unwrap();commit(&dir,first["token"].as_str().unwrap()).unwrap();let next=preview(&dir,&archive(b"new"),"test",None).unwrap();fs::create_dir(root(&dir).join("registry.json.tmp")).unwrap();assert!(commit(&dir,next["token"].as_str().unwrap()).is_err());assert_eq!(fs::read(root(&dir).join("installed/org.example.rollback/clock.html")).unwrap(),b"old");assert_eq!(list(&dir).unwrap()[0].manifest["id"],"org.example.rollback");fs::remove_dir_all(dir).unwrap();}
}
